from lib import *
S = SS('t5')
steps = [
    step("XA 语句的状态机,逐条试出来:XA START 'x1' 后写一行订单;此时直接 COMMIT 报 1399 XAER_RMFAIL(全局事务在 ACTIVE 状态下不能执行这条命令);没有 XA END 就 XA PREPARE 同样报 1399。XA END 之后事务进入 IDLE 状态,再写订单还是 1399(IDLE 状态下不能写)。XA PREPARE 成功后,同一连接仍能执行 SELECT 1。另一个会话此时看到订单数 0(prepare 了但还没 commit,不可见)。XA RECOVER 返回 (1, 2, 0, 'x1'),四列是 formatID、gtrid 长度、bqual 长度、xid 数据——没有 prepare 的时间。换另一个会话 XA COMMIT 'x1' 成功,订单数变成 1,XA RECOVER 清空。", t=tl(S(1)), mark=lidx(S(1), 'ACTIVE state', 'IDLE state'), done=lidx(S(1), 'XA RECOVER: ((1, 2, 0', '提交后订单数'), kv=KV([['ACTIVE', '不能 COMMIT / PREPARE,要先 XA END'], ['IDLE', '不能再写,只能 PREPARE / ROLLBACK'], ['XA RECOVER', '只有 xid,没有 prepare 时间']], ['XA RECOVER'])),
    step("连接断开会怎样。XA START、INSERT、XA END 之后断开连接(还没 PREPARE):XA RECOVER 为空,订单数 0——没 prepare 的 XA 事务随连接一起回滚。XA PREPARE 之后断开连接:XA RECOVER 里还有 y2,订单数仍是 0;换一个连接 XA COMMIT 'y2' 成功,订单数变成 1。prepare 之前事务属于连接,prepare 之后事务属于服务端,谁都能收尾。", t=tl(S(2)), mark=lidx(S(2), 'XA PREPARE 之后断开连接'), done=lidx(S(2), '换一个连接'), b=bars([['XA END 后断开:XA RECOVER 条数', 0, '0(回滚)'], ['PREPARE 后断开:XA RECOVER 条数', 1, '1(留下)']], 1, mark=[0], done=[1]), kv=KV([['prepare 之前断开', '随连接回滚'], ['prepare 之后断开', '留在服务端'], ['收尾', '任何连接都能 XA COMMIT']], ['prepare 之后断开'])),
    step("prepare 之后行锁一直握着。别的会话 SELECT 读到旧值 100;UPDATE 同一行等了 2004.2 ms 后报 1205 Lock wait timeout(这里把 innodb_lock_wait_timeout 设成了 2 秒,默认是 50 秒)。information_schema.innodb_trx 里这个已经没有连接的 prepared 事务显示 trx_state=RUNNING、trx_mysql_thread_id=0、锁了 1 行——从这个视图里看不出它是 prepared。", t=tl(S(3)), mark=lidx(S(3), '等了 2004.2 ms'), done=lidx(S(3), 'trx_mysql_thread_id', '旧值'), b=bars([['SELECT 读到的 qty', 100, '100(旧值)'], ['UPDATE 被挡 ms', 2004.2, '2004.2(超时)']], 2100, done=[0], mark=[1]), kv=KV([['读', '旧值,不被挡'], ['写同一行', '等到 innodb_lock_wait_timeout'], ['innodb_trx', '显示 RUNNING,线程号 0']], ['innodb_trx'])),
    step("prepare 之后 kill -9 整个 mysqld(此时 k1 已 PREPARE,k2 还在 ACTIVE)。重启用了 611.1 ms,错误日志里有 “Found 1 prepared XA transactions”。重启后 XA RECOVER 里只有 k1;k2 插入的订单数是 0(没 prepare 的随崩溃消失);别的会话 UPDATE 同一行仍然 1205 超时(行锁在恢复时被重新持有);XA COMMIT 'k1' 成功,qty 变成 99。binlog 里记着每个 XA 事务的 XA START、XA END 和一条 XA_prepare 事件(XA PREPARE),k1 的 XA COMMIT 出现在重启后新的 binlog.000002 里。", t=tl(S(4)), mark=lidx(S(4), '重启后 XA RECOVER', '行锁在恢复时'), done=lidx(S(4), 'XA COMMIT 之后 qty = 99', "binlog.000002"), kv=KV([['prepared', '重启后还在,锁被恢复'], ['没 prepare 的', '重启后消失'], ['binlog', 'XA_prepare 事件 + XA COMMIT']], ['prepared'])),
    step("代价(每种写法 3 轮交替、共 600 次,每次往订单表 INSERT 一行并往库存表 UPDATE 一行)。普通事务:中位数 0.2 ms、p99 0.4 ms、每个事务 1.01 次 redo fsync。XA 在同一个实例里走完 prepare 和 commit:中位数 0.3 ms(1.8 倍)、3.00 次 fsync。XA 跨两个实例:中位数 0.6 ms(3.4 倍)、p99 1.7 ms、6.02 次 fsync(两个实例合计)。按语句拆开平均:普通事务 COMMIT 1.08;XA 事务 XA PREPARE 1.10、XA COMMIT 2.06,其余语句都在 0.04 到 0.12 的本底噪声内。XA COMMIT 为什么要两次,我没有深究。", t=tl(S(5)), mark=lidx(S(5), 'XA(跨两个实例)', 'XA 事务:'), done=lidx(S(5), '普通事务(一个实例)'), b=bars([['普通事务 fsync/事务', 1.01, '1.01'], ['XA 同实例 fsync/事务', 3.00, '3.00'], ['XA 跨两实例 fsync/事务', 6.02, '6.02'], ['XA 跨两实例 中位数 ms', 0.6, '0.6']], 6.5, cur=[0], mark=[1, 2], done=[3]), kv=KV([['fsync', '1 → 3(单实例 XA)→ 6(跨两个实例)'], ['中位数', '0.2 → 0.3 → 0.6 ms'], ['未计入', 'binlog 的 fsync']], ['fsync'])),
]
A = mkartt('t5', 5, '分布式事务,XA,MySQL,两阶段提交,XA RECOVER,真实验证,动画演示',
    '实测 MySQL 的 XA 事务:状态机里 ACTIVE 不能 COMMIT、IDLE 不能写;prepare 之前断开连接会回滚、prepare 之后留在服务端;prepared 事务的行锁让别的写等到 1205 超时;kill -9 重启后 XA RECOVER 能看到、锁被恢复;跨两个实例的 XA 比普通事务多 5 次 redo fsync、中位数 3.4 倍。',
    'XA 是数据库对两阶段提交的标准接口。MySQL 的 XA START、XA END、XA PREPARE、XA COMMIT 各自处于什么状态?连接断开、实例崩溃后 prepared 事务去哪了?代价多大?这篇用真实的 MySQL 26.7 逐条试出来。',
    [('6.02 次', '跨两个 MySQL 实例的一次 XA 事务引起的 redo fsync(普通事务是 1.01 次)'), ('3.4 倍', '跨两个实例的 XA 提交延迟中位数相对普通事务'), ('611.1 ms', 'prepare 之后 kill -9 的 mysqld 重启用时,重启后 XA RECOVER 里还有这个事务')],
    [('XA 的状态机', '<p>XA START 之后是 ACTIVE,不能直接 COMMIT 或 PREPARE;XA END 之后是 IDLE,不能再写;XA PREPARE 之后才可以被任何会话 XA COMMIT 或 XA ROLLBACK。XA RECOVER 只给 xid,没有 prepare 了多久。</p>'),
     ('prepare 前后连接的作用', '<p>没有 prepare 的 XA 事务随连接一起回滚;prepare 之后事务属于服务端,断开连接后换一个连接就能收尾。</p>'),
     ('prepared 事务的锁', '<p>行锁一直持有:读不被挡,写同一行等到 innodb_lock_wait_timeout。在 information_schema.innodb_trx 里它显示成 RUNNING、线程号 0,不容易认出来。</p>'),
     ('崩溃恢复', '<p>prepare 之后 mysqld 被 kill -9,重启后 XA RECOVER 里还在、锁被恢复,没 prepare 的 XA 事务消失。binlog 里有 XA_prepare 事件。</p>'),
     ('代价', '<p>XA 提交 = XA PREPARE 约 1 次 + XA COMMIT 约 2 次 redo fsync,单个实例就是 3 次,跨两个实例 6 次,中位数 3.4 倍。</p>')],
    steps,
    [ENV_T + '。本篇用两个独立的 MySQL 26.7.0 实例(binlog_format=ROW,sync_binlog=1,innodb_flush_log_at_trx_commit=1,innodb_lock_wait_timeout 在实验里设成 2 秒),客户端是 PyMySQL;redo fsync 数来自 Innodb_os_log_fsyncs 状态变量,不含 binlog 的 fsync;MySQL 在 macOS 上的 fsync 很便宜,倍数比绝对值更有参考价值',
     '没有验证:XA COMMIT 为什么引起约 2 次 redo fsync(没有深究);MySQL 的 XA 在主从复制下的行为;Java 里 Atomikos / Narayana 这类事务管理器怎么驱动 XA;长时间悬挂的 prepared 事务对 binlog 清理和复制的影响;PostgreSQL、MySQL 以外的数据库的 XA 实现'],
    'MySQL XA')
